def caesar_cipher(text, shift):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            n = ord(char) - ord('a')
            shifted = (n + shift) % 26
            result.append(chr(shifted + ord('a')))
        elif 'A' <= char <= 'Z':
            n = ord(char) - ord('A')
            shifted = (n + shift) % 26
            result.append(chr(shifted + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

