def word_frequency(text: str) -> dict[str, int]:
    words = text.split()
    freq_dict = {}
    for word in words:
        cleaned_word = word.strip(string.punctuation).lower()
        if cleaned_word:
            freq_dict[cleaned_word] = freq_dict.get(cleaned_word, 0) + 1
    return freq_dict
